les.","tree":{"sha":"992417a56cb7b9bfccc3f4e8ba39e32352e0147a","url":"https://api.github.com/repos/MuskStark/FengYu/git/trees/992417a56cb7b9bfccc3f4e8ba39e32352e0147a"},"url":"https://api.github.com/repos/MuskStark/FengYu/git/commits/46ca6ec1f54e4922c3e85cf711eeec6f085fd693","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/138420547?v=4","events_url":"https://api.github.com/users/MuskStark/events{/privacy}","followers_url":"https://api.github.com/users/MuskStark/followers","following_url":"https://api.github.com/users/MuskStark/following{/other_user}","gists_url":"https://api.github.com/users/MuskStark/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/MuskStark","id":138420547,"login":"MuskStark","node_id":"U_kgDOCEAhQw","organizations_url":"https://api.github.com/users/MuskStark/orgs","received_events_url":"https://api.github.com/users/MuskStark/received_events","repos_url":"https://api.github.com/users/MuskStark/repos","site_admin":false,"starred_url":"https://api.github.com/users/MuskStark/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/MuskStark/subscriptions","type":"User","url":"https://api.github.com/users/MuskStark","user_view_type":"public"},"html_url":"https://github.com/MuskStark/FengYu/commit/46ca6ec1f54e4922c3e85cf711eeec6f085fd693","node_id":"C_kwDORYbX49oAKDQ2Y2E2ZWMxZjU0ZTQ5MjJjM2U4NWNmNzExZWVlYzZmMDg1ZmQ2OTM","parents":[{"html_url":"https://github.com/MuskStark/FengYu/commit/09a935c9f8292ad1666e7555682af21d9ded7720","sha":"09a935c9f8292ad1666e7555682af21d9ded7720","url":"https://api.github.com/repos/MuskStark/FengYu/commits/09a935c9f8292ad1666e7555682af21d9ded7720"}],"sha":"46ca6ec1f54e4922c3e85cf711eeec6f085fd693","url":"https://api.github.com/repos/MuskStark/FengYu/commits/46ca6ec1f54e4922c3e85cf711eeec6f085fd693"},{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/138420547?v=4","events_url":"https://api.github.com/users/MuskStark/events{/privacy}","followers_url":"https://api.github.com/users/MuskStark/followers","following_url":"https://api.github.com/users/MuskStark/following{/other_user}","gists_url":"https://api.github.com/users/MuskStark/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/MuskStark","id":138420547,"login":"MuskStark","node_id":"U_kgDOCEAhQw","organizations_url":"https://api.github.com/users/MuskStark/orgs","received_events_url":"https://api.github.com/users/MuskStark/received_events","repos_url":"https://api.github.com/users/MuskStark/repos","site_admin":false,"starred_url":"https://api.github.com/users/MuskStark/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/MuskStark/subscriptions","type":"User","url":"https://api.github.com/users/MuskStark","user_view_type":"public"},"comments_url":"https://api.github.com/repos/MuskStark/FengYu/commits/09a935c9f8292ad1666e7555682af21d9ded7720/comments","commit":{"author":{"date":"2026-09-30T08:42:54Z","email":"gitman@outlook.sg","name":"MuskStark"},"comment_count":0,"committer":{"date":"2026-09-30T08:42:54Z","email":"gitman@outlook.sg","name":"MuskStark"},"message":"👷 ci(toolchain): install the frontend''s vuetify types before the local consumer smoke\n\nThe local-consumer-smoke job had never actually run — the build job ahead\nof it failed first — and its first execution died typechecking toolchain/ui\nwith the same \"Cannot find module ''vuetify''\" the build job hit: the\nplugin-ui theme-equality spec imports frontend/src/plugins/md3-themes.ts,\nwhose vuetify types resolve through the frontend''s node_modules. The smoke\nscript now installs the frontend deps itself (it already self-installs\nevery other prerequisite, so local developers get the fix too), and the\njob''s setup-node cache covers frontend/yarn.lock.\n\nVerified by a full local run: PASS, clean local plugin consumer lifecycle.","tree":{"sha":"f721216b629c86d762568452acea502210a0c616","url":"https://api.github.com/repos/MuskStark/FengYu/git/trees/f721216b629c86d762568452acea502210a0c616"},"url":"https://api.github.com/repos/MuskStark/FengYu/git/commits/09a935c9f8292ad1666e7555682af21d9ded7720","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/138420547?v=4","events_url":"https://api.github.com/users/MuskStark/events{/privacy}","followers_url":"https://api.github.com/users/MuskStark/followers","following_url":"https://api.github.com/users/MuskStark/following{/other_user}","gists_url":"https://api.github.com/users/MuskStark/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/MuskStark","id":138420547,"login":"MuskStark","node_id":"U_kgDOCEAhQw","organizations_url":"https://api.github.com/users/MuskStark/orgs","received_events_url":"https://api.github.com/users/MuskStark/received_events","repos_url":"https://api.github.com/users/MuskStark/repos","site_admin":false,"starred_url":"https://api.github.com/users/MuskStark/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/MuskStark/subscriptions","type":"User","url":"https://api.github.com/users/MuskStark","user_view_type":"public"},"html_url":"https://github.com/MuskStark/FengYu/commit/09a935c9f8292ad1666e7555682af21d9ded7720","node_id":"C_kwDORYbX49oAKDA5YTkzNWM5ZjgyOTJhZDE2NjZlNzU1NTY4MmFmMjFkOWRlZDc3MjA","parents":[{"html_url":"https://github.com/MuskStark/FengYu/commit/197c1aca951e0e7a2838ce3a43e6acadcf2c1dd6","sha":"197c1aca951e0e7a2838ce3a43e6acadcf2c1dd6","url":"https://api.github.com/repos/MuskStark/FengYu/commits/197c1aca951e0e7a2838ce3a43e6acadcf2c1dd6"}],"sha":"09a935c9f8292ad1666e7555682af21d9ded7720","url":"https://api.github.com/repos/MuskStark/FengYu/commits/09a935c9f8292ad1666e7555682af21d9ded7720"},{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/138420547?v=4","events_url":"https://api.github.com/